app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /healthz - Readiness probe endpoint
// Returns 200 + {"db":"ok"} when Postgres is up
// Returns 503 when the DB check fails
app.get('/healthz', async (req, res) => {
  try {
    // Check PostgreSQL connection using a simple query
    if (!global.db) {
      // Import the DB client only when needed
      const { Pool } = require('pg');
      const connectionString = process.env.DATABASE_URL;
      if (!connectionString) {
        throw new Error('DATABASE_URL not set');
      }
      global.db = new Pool({ connectionString });
    }

    const client = await global.db.connect();
    try {
      await client.query('SELECT 1');
      res.json({ db: 'ok' });
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(503).json({ error: 'service unavailable' });
  }
});

