    client.connect();
    process.env.DATABASE_URL = secrets.DATABASE_URL;

    res.json({ status: 'success', message: 'Secrets registered successfully' });
  } catch (error) {
    console.error('CI secret sync error:', error);
    res.status(500).json({ error: 'Failed to sync secrets' });
  }
});

