const express = require('express');
const app = express();

// Health check db connection function
let dbConnection = null;
let dbStatus = 'unknown';

async function checkDatabaseConnection() {
  try {
    if (!dbConnection) {
      // Parse DATABASE_URL from env
      const databaseUrl = process.env.DATABASE_URL;
      if (!databaseUrl) {
        throw new Error('DATABASE_URL not found in environment');
      }

      // For production, this would be a real PostgreSQL connection
      // For this implementation, we'll create a mock connection function
      // that simulates checking a PostgreSQL connection
      await new Promise((resolve, reject) => {
        // Simulate database check
        // In a real implementation, this would connect to PostgreSQL
        const checkInterval = setInterval(() => {
          if (dbStatus === 'ok') {
            clearInterval(checkInterval);
            resolve();
          } else if (dbStatus === 'error') {
            clearInterval(checkInterval);
            reject(new Error('Database connection failed'));
          }
        }, 100);

        // Timeout after 5 seconds
        setTimeout(() => {
          clearInterval(checkInterval);
          if (dbStatus === 'ok') {
            resolve();
          } else {
            reject(new Error('Database connection timeout'));
          }
        }, 5000);
      });
    }

    dbStatus = 'ok';
    return true;
  } catch (error) {
    console.error('Database health check failed:', error.message);
    dbStatus = 'error';
    return false;
  }
}

// Initialize DB check
checkDatabaseConnection().catch(err => {
  console.error('Failed to initialize database connection check:', err.message);
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  const isHealthy = await checkDatabaseConnection();

  if (isHealthy) {
    res.status(200).json({ db: 'ok' });
  } else {
    res.status(503).json({ db: 'unhealthy' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

