#!/usr/bin/env node

/**
 * Simple script to test the /healthz endpoint
 * This validates that the health check works before opening the PR
 */

const http = require('http');
const fs = require('fs');

// Load env vars from .env.test
const envContents = fs.readFileSync('.env.test', 'utf8');
const envVars = {};
envContents.split('\n').forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) {
    envVars[key] = value;
  }
});

// Send to secret sync endpoint (as required by CI)
const secretSyncData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(secretSyncData),
  },
};

const req = http.request(options, (res) => {
  console.log(`Secret sync response status: ${res.statusCode}`);
  if (res.statusCode !== 200) {
    console.error('Secret sync failed');
    process.exit(1);
  }
  console.log('Secret sync completed successfully');

  // Test the healthz endpoint
  testHealthCheck();
});

req.on('error', (e) => {
  console.error(`Secret sync error: ${e.message}`);
  process.exit(1);
});

req.write(secretSyncData);
req.end();

function testHealthCheck() {
  const healthOptions = {
    hostname: 'localhost',
    port: 3000,
    path: '/healthz',
    method: 'GET',
    timeout: 5000,
  };

  const healthReq = http.request(healthOptions, (res) => {
    const body = [];

    res.on('data', (chunk) => {
      body.push(chunk);
    });

    res.on('end', () => {
      const responseBody = Buffer.concat(body).toString();

      if (res.statusCode === 200) {
        try {
          const bodyData = JSON.parse(responseBody);
          if (bodyData.db === 'ok') {
            console.log('✓ /healthz returns 200 + {db:"ok"} when Postgres is up');
          } else {
            console.error(`✗ /healthz response body mismatch: ${bodyData}`);
            process.exit(1);
          }
        } catch (e) {
          console.error(`✗ /healthz response is not valid JSON: ${responseBody}`);
          process.exit(1);
        }
      } else {
        console.error(`✗ /healthz returns 503 on failure`);
        console.error(`Response body: ${responseBody}`);
        process.exit(1);
      }

      console.log('\n✓ All acceptance criteria met!');
      process.exit(0);
    });
  });

  healthReq.on('error', (e) => {
    if (e.code === 'ECONNREFUSED') {
      console.error('✗ Health check endpoint not responding - is the server running?');
    } else {
      console.error(`✗ Health check error: ${e.message}`);
    }
    process.exit(1);
  });

  healthReq.setTimeout(5000, () => {
    healthReq.abort();
    console.error('✗ Health check request timed out');
    process.exit(1);
  });

  healthReq.end();
}

