console.log(`Testing ${url}...`);

const req = http.get(url, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`\n✓ GET /healthz returned status ${res.statusCode}`);

    try {
      const body = JSON.parse(data);
      console.log('✓ Response body:', JSON.stringify(body, null, 2));

      if (res.statusCode !== 200) {
        console.error(`✗ Expected status 200, got ${res.statusCode}`);
        process.exit(1);
      }

      if (body.db !== 'ok') {
        console.error('✗ Expected "db": "ok"', 'Got:', body.db);
        process.exit(1);
      }

      console.log('✓ Response has "db: ok" as expected');
      console.log('\n✅ All healthz endpoint tests passed!\n');
      process.exit(0);
    } catch (err) {
      console.error('✗ Failed to parse JSON response:', err.message);
      console.error('Response data:', data);
      process.exit(1);
    }
  });
});

req.on('error', (err) => {
  console.error('✗ Request failed:', err.message);
  process.exit(1);
});

// Set timeout
req.setTimeout(5000, () => {
  console.error('✗ Request timeout');
  req.destroy();
  process.exit(1);
});

