const express = require('express');
const pg = require('pg');

const app = express();
const PORT = process.env.PORT || 3000;

// Parse JSON bodies
app.use(express.json());

// Database connection pool
const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
});

// Helper function to check database health
async function checkDatabaseHealth() {
  try {
    const result = await pool.query('SELECT NOW()');
    return { status: 'ok', timestamp: result.rows[0]?.now || new Date().toISOString() };
  } catch (error) {
    console.error('Database health check failed:', error.message);
    return { status: 'error', error: error.message };
  }
}

// Health check endpoint (returned 200 when database is up)
app.get('/healthz', async (req, res) => {
  const dbHealth = await checkDatabaseHealth();

  if (dbHealth.status === 'ok') {
    res.status(200).json({ db: 'ok' });
  } else {
    res.status(503).json({ db: 'unhealthy', error: dbHealth.error });
  }
});

// Traditional /health endpoint for backward compatibility
app.get('/health', async (req, res) => {
  const dbHealth = await checkDatabaseHealth();

  if (dbHealth.status === 'ok') {
    res.json({ status: 'ok', timestamp: dbHealth.timestamp });
  } else {
    res.status(503).json({ status: 'degraded', error: dbHealth.error });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

